def merge_intervals(intervals):
    if not intervals:
        return []

    sorted_intervals = sorted(intervals, key=lambda x: x[0])
    merged = [list(sorted_intervals[0])]

    for start, end in sorted_intervals[1:]:
        if start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    return merged

import heapq

def toposort(nodes, edges):
    indegree = {node: 0 for node in nodes}
    adjacent = {node: set() for node in nodes}

    for source, destination in edges:
        if destination not in adjacent[source]:
            adjacent[source].add(destination)
            indegree[destination] += 1

    available = [node for node in nodes if indegree[node] == 0]
    heapq.heapify(available)
    result = []

    while available:
        node = heapq.heappop(available)
        result.append(node)

        for neighbor in adjacent[node]:
            indegree[neighbor] -= 1
            if indegree[neighbor] == 0:
                heapq.heappush(available, neighbor)

    if len(result) != len(nodes):
        raise ValueError("cycle detected")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError

    batches = []
    current_batch = []
    current_sum = 0

    for name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError

        if current_sum + weight <= limit:
            current_batch.append(name)
            current_sum += weight
        else:
            batches.append(current_batch)
            current_batch = [name]
            current_sum = weight

    if current_batch:
        batches.append(current_batch)

    return batches

import re

def parse_env(text):
    env = {}
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        if "=" not in line:
            raise ValueError(f"Invalid environment line: {line}")
        key, value = line.split("=", 1)
        key = key.strip()
        value = value.strip()
        if not re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key):
            raise ValueError(f"Invalid environment key: {key}")
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        env[key] = value
    return env

import codecs

def parse_sse(chunks):
    decoder = codecs.getincrementaldecoder("utf-8")()
    events = []
    data_lines = []
    current_line = ""

    def dispatch():
        nonlocal data_lines
        if data_lines:
            data = "\n".join(data_lines)
            if data == "[DONE]":
                return True
            events.append(data)
        data_lines = []
        return False

    for chunk in chunks:
        text = decoder.decode(chunk)
        for ch in text:
            if ch == "\n":
                line = current_line
                if line.endswith("\r"):
                    line = line[:-1]

                if line == "":
                    if dispatch():
                        return events
                elif ":" in line and not line.startswith(":"):
                    field, value = line.split(":", 1)
                    if field == "data":
                        if value.startswith(" "):
                            value = value[1:]
                        data_lines.append(value)

                current_line = ""
            else:
                current_line += ch

    return events

import math

def retry_delay(attempt, base, cap):
    if attempt < 0 or base < 0 or cap < 0:
        raise ValueError("attempt, base, and cap must be nonnegative")
    if base == 0 or cap == 0:
        return 0.0
    try:
        value = math.ldexp(float(base), attempt)
    except OverflowError:
        return float(cap)
    return float(min(cap, value))

def fifo_admit(active, queued, budget, slots):
    if any(q > budget for q in queued):
        raise ValueError("Queued reservation exceeds budget")

    token_remaining = budget - sum(active)
    slot_remaining = slots - len(active)
    admitted = []

    for q in queued:
        if q > token_remaining or slot_remaining <= 0:
            break
        admitted.append(q)
        token_remaining -= q
        slot_remaining -= 1

    remaining = queued[len(admitted):]
    return (admitted, remaining)
